  "marketplace.features.offers.api.route.submitted.offer.not.found": "Submitted offer not found.",
  "marketplace.features.offers.api.runtime.catalog.item.not.found": "Catalog item not found.",
  "marketplace.features.offers.api.runtime.offer.could.not.be.accepted": "Offer could not be accepted.",
  "marketplace.features.offers.api.runtime.offer.not.found": "Offer not found.",
  "marketplace.features.offers.api.runtime.offer.product.id.does.not.match": "Offer product id does not match the selected options.",
  "marketplace.features.offers.api.runtime.offers.may.only.reference.active.catalog": "Offers may only reference active catalog items.",
  "marketplace.features.offers.api.runtime.seller.does.not.have.enough.active": "Seller does not have enough active supply to accept this offer.",
  "marketplace.features.offers.readModel.queries.offer.buyer.display.name.as.buyer": "\n  offer.*,\n  buyer.display_name AS buyer_display_name,\n  buyer.average_rating::text AS buyer_average_rating,\n  COALESCE(buyer.review_count, 0)::integer AS buyer_review_count,\n  matched_listing.listing_id,\n  matched_listing.listing_price_amount::text AS listing_price_amount,\n  matched_listing.listing_quantity_cap,\n  matched_listing.listing_visible_quantity,\n  matched_listing.listing_visible_quantity AS seller_available_quantity,\n  (matched_listing.listing_price_amount - offer.price_amount)::numeric(12,2)::text AS offer_price_gap_amount,\n  CASE\n    WHEN matched_listing.listing_price_amount > 0\n      THEN ROUND((offer.price_amount / matched_listing.listing_price_amount) * 10000)::integer\n    ELSE 0\n  END AS offer_to_listing_price_bps,\n  COALESCE(availability.status, 'available') AS seller_listing_availability_status",
  "marketplace.features.offers.readModel.queries.offer.not.found": "Offer not found.",
  "marketplace.features.offers.readModel.queries.offer.status.submitted.and.exists.select": "\n(\n  (\n    offer.status = 'submitted'\n    AND EXISTS (\n      SELECT 1\n      FROM marketplace_listing_pages AS listing\n      WHERE listing.account_id = $1\n        AND listing.status = 'active'\n        AND listing.product_id = offer.product_id\n    )\n  )\n  OR (\n    offer.status = 'accepted'\n    AND offer.accepted_seller_account_id = $1\n  )\n)",
  "marketplace.features.offers.readModel.schema.create.table.if.not.exists.marketplace": "\nCREATE TABLE IF NOT EXISTS marketplace_offer_pages (\n  offer_id text PRIMARY KEY,\n  buyer_account_id text NOT NULL,\n  catalog_catalog_item_id text NOT NULL,\n  product_id text NOT NULL,\n  item_title text NOT NULL,\n  item_subtitle text NULL,\n  selected_options jsonb NOT NULL DEFAULT '[]'::jsonb,\n  product_summary text NULL,\n  shipping_destination_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,\n  price_amount numeric(12,2) NOT NULL,\n  quantity_requested integer NOT NULL CHECK (quantity_requested > 0),\n  status text NOT NULL DEFAULT 'submitted',\n  accepted_seller_account_id text NULL,\n  accepted_at timestamptz NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS marketplace_offer_pages_buyer_account_idx\n  ON marketplace_offer_pages (buyer_account_id, updated_at DESC);\n\nCREATE INDEX IF NOT EXISTS marketplace_offer_pages_catalog_catalog_item_idx\n  ON marketplace_offer_pages (catalog_catalog_item_id, status, updated_at DESC);\n\nCREATE INDEX IF NOT EXISTS marketplace_offer_pages_catalog_version_idx\n  ON marketplace_offer_pages (product_id, status, updated_at DESC);\n\nCREATE INDEX IF NOT EXISTS marketplace_offer_pages_selected_options_idx\n  ON marketplace_offer_pages USING gin (selected_options);\n\nALTER TABLE marketplace_offer_pages\n  ADD COLUMN IF NOT EXISTS shipping_destination_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb;\n",
