  "reputation.features.reviews.integrations.source.sourceSchema.create.table.if.not.exists.reputation": "\nCREATE TABLE IF NOT EXISTS marketplace_review_account_sources (\n  account_id text PRIMARY KEY,\n  display_name text NOT NULL,\n  status text NOT NULL,\n  updated_at timestamptz NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS marketplace_review_account_sources_status_idx\n  ON marketplace_review_account_sources (status, updated_at DESC, account_id ASC);\n\nCREATE TABLE IF NOT EXISTS marketplace_review_order_sources (\n  order_id text PRIMARY KEY,\n  buyer_account_id text NOT NULL,\n  seller_account_id text NOT NULL,\n  status text NOT NULL,\n  created_at timestamptz NOT NULL,\n  updated_at timestamptz NOT NULL,\n  cancelled_at timestamptz NULL,\n  ready_for_fulfillment_at timestamptz NULL\n);\n\nCREATE INDEX IF NOT EXISTS marketplace_review_order_sources_buyer_idx\n  ON marketplace_review_order_sources (buyer_account_id, updated_at DESC, order_id DESC);\n\nCREATE INDEX IF NOT EXISTS marketplace_review_order_sources_seller_idx\n  ON marketplace_review_order_sources (seller_account_id, updated_at DESC, order_id DESC);\n\nCREATE TABLE IF NOT EXISTS marketplace_review_shipment_sources (\n  shipment_id text PRIMARY KEY,\n  order_id text NOT NULL,\n  status text NOT NULL,\n  created_at timestamptz NOT NULL,\n  updated_at timestamptz NOT NULL,\n  dispatched_at timestamptz NULL,\n  delivered_at timestamptz NULL,\n  returned_at timestamptz NULL,\n  exception_raised_at timestamptz NULL\n);\n\nCREATE INDEX IF NOT EXISTS marketplace_review_shipment_sources_order_idx\n  ON marketplace_review_shipment_sources (order_id, updated_at DESC, shipment_id DESC);\n",
  "reputation.features.reviews.readModel.queries.select.page.review.id.page.order": "\n  SELECT\n    page.review_id,\n    page.order_id,\n    page.author_account_id,\n    author.display_name AS author_display_name,\n    page.subject_account_id,\n    subject.display_name AS subject_display_name,\n    page.author_role,\n    page.rating,\n    page.feedback,\n    page.status,\n    page.submitted_at,\n    page.updated_at,\n    page.withdrawn_at\n  FROM marketplace_review_pages AS page\n  LEFT JOIN marketplace_review_account_sources AS author\n    ON author.account_id = page.author_account_id\n  LEFT JOIN marketplace_review_account_sources AS subject\n    ON subject.account_id = page.subject_account_id\n",
  "reputation.features.reviews.readModel.schema.create.table.if.not.exists.reputation": "\nCREATE TABLE IF NOT EXISTS marketplace_review_pages (\n  review_id text PRIMARY KEY,\n  order_id text NOT NULL,\n  author_account_id text NOT NULL,\n  subject_account_id text NOT NULL,\n  author_role text NOT NULL,\n  rating integer NOT NULL,\n  feedback text NULL,\n  status text NOT NULL,\n  submitted_at timestamptz NOT NULL,\n  updated_at timestamptz NOT NULL,\n  withdrawn_at timestamptz NULL\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS marketplace_active_review_direction_idx\n  ON marketplace_review_pages (order_id, author_account_id, subject_account_id)\n  WHERE status = 'active';\n\nCREATE INDEX IF NOT EXISTS marketplace_review_pages_author_idx\n  ON marketplace_review_pages (author_account_id, updated_at DESC, review_id DESC);\n\nCREATE INDEX IF NOT EXISTS marketplace_review_pages_subject_idx\n  ON marketplace_review_pages (subject_account_id, updated_at DESC, review_id DESC)\n  WHERE status = 'active';\n\nCREATE TABLE IF NOT EXISTS marketplace_review_summary_pages (\n  account_id text PRIMARY KEY,\n  average_rating numeric(4, 2) NULL,\n  review_count integer NOT NULL DEFAULT 0,\n  rating_1_count integer NOT NULL DEFAULT 0,\n  rating_2_count integer NOT NULL DEFAULT 0,\n  rating_3_count integer NOT NULL DEFAULT 0,\n  rating_4_count integer NOT NULL DEFAULT 0,\n  rating_5_count integer NOT NULL DEFAULT 0,\n  updated_at timestamptz NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS marketplace_review_eligibility_pages (\n  order_id text NOT NULL,\n  author_account_id text NOT NULL,\n  subject_account_id text NOT NULL,\n  author_role text NOT NULL,\n  eligible_at timestamptz NOT NULL,\n  updated_at timestamptz NOT NULL,\n  PRIMARY KEY (order_id, author_account_id, subject_account_id)\n);\n\nCREATE INDEX IF NOT EXISTS marketplace_review_eligibility_author_idx\n  ON marketplace_review_eligibility_pages (author_account_id, eligible_at DESC, order_id DESC);\n",
